import {SKILLS,skillById,profileSummary,localDay} from './engine.mjs';
import {DOMAINS,syllabusIds,domainFor} from './curriculum.mjs';
import {competency,planSummary,probeIds} from './adaptive.mjs';
import {esc,icon,mathText} from './visuals.mjs';
import {avatarSVG,clubBadge} from './avatar.mjs';
import {ITEMS,CLUBS,POSITIONS,SKIN_TONES,HAIR_COLOURS,credits,careerLevel,careerXP,levelProgress,xpForLevel,owns,clubById,initCareer,clubProgress} from './career.mjs';
import {yearProgress,leagueTable} from './promotion.mjs';
import {focusTables,tableEvidence} from './tables.mjs';
import {goalsMarkup,factMapMarkup} from './experience.mjs';
import {britishVoices} from './speech.mjs';

const nav=(view,label,symbol='arrow',className='btn white')=>`<button class="${className}" data-action="nav" data-view="${view}">${icon(symbol,17)}${label}</button>`;
const heading=(eyebrow,title,aside='')=>`<div class="heading academy-page-heading"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1></div>${aside}</div>`;
const progressStrip=p=>{const v=levelProgress(p);return `<div class="career-progress"><div><b>Level ${v.level}</b><span>${Math.floor(v.current)} / ${v.needed} XP</span></div><div class="xp"><i style="width:${v.percent}%"></i></div><small>Next level: ${v.needed-Math.floor(v.current)} XP</small></div>`;};
export function pickerView(data){
 const players=data.profiles;
 return `<section class="academy-welcome"><div class="welcome-copy"><span class="eyebrow">The number academy · Years 1–6</span><h1>Your player.<br><em>Your next goal.</em></h1><p>Build your player. Pick your year. Play.</p><button class="btn lime big" data-action="new-player">${icon('plus',18)} Create your player</button><div class="welcome-trust">${icon('shield',14)} Your progress stays on this device.</div></div><div class="welcome-character">${avatarSVG(null,{size:230})}<span class="avatar-label">Your number. Your kit. Your game.</span><i class="welcome-orbit orbit-one"></i><i class="welcome-orbit orbit-two"></i></div></section>${players.length?`<div class="section-head"><h2>Your squad</h2><button class="text-btn" data-action="new-player">Add a player ${icon('plus',14)}</button></div><div class="squad-cards">${players.map(p=>{initCareer(p);return `<button class="squad-player" data-action="choose-player" data-id="${p.id}" aria-label="Play as ${esc(p.name)}, Year ${p.year}"><div class="squad-info">${clubBadge(p)}<span>Year ${p.year} · Level ${careerLevel(p)}</span><h2>${esc(p.name)}</h2><small>${esc(p.look.position)} · No. ${p.look.number}</small><span class="squad-play">Play ${icon('arrow',17)}</span></div>${avatarSVG(p,{size:106})}</button>`;}).join('')}</div>`:'<div class="first-player-note">'+icon('ball',20)+'<span>Your academy starts with you.</span></div>'}<div class="welcome-foot"><button class="text-btn" data-action="browse">Explore Years 1–6 ${icon('arrow',14)}</button><a class="text-btn" href="../">For parents & teachers ${icon('book',14)}</a></div>`;
}
export function yearJourney(p,selectedYear=p.year){
 const progress=yearProgress(p,selectedYear),explored=progress.skills.filter(s=>s.n>0).length;
 return `<section class="year-journey panel"><div class="section-head"><div><span class="eyebrow">Your academy pathway</span><h2>Every year. A stronger player.</h2></div><span class="year-count">${(p.completedYears||[]).length}<small> / 6 years</small></span></div><div class="year-path">${Array.from({length:6},(_,i)=>i+1).map(y=>`<button class="year-stop ${(p.completedYears||[]).includes(y)?'complete':y===p.year?'current':''}" data-action="view-year" data-year="${y}" ${y===p.year?'aria-current="step"':''}><span>${(p.completedYears||[]).includes(y)?icon('check',21):y}</span><b>Year ${y}</b><small>${(p.completedYears||[]).includes(y)?'Complete':y===p.year?'Your year':'Explore'}</small></button>`).join('')}</div><div class="year-progress-detail"><div><b>Year ${selectedYear}</b><span>${explored}/${progress.total} skills explored · ${progress.secure} match fit</span></div><div class="dual-progress"><i style="width:${explored/progress.total*100}%"></i><b style="width:${progress.secure/progress.total*100}%"></b></div></div>${selectedYear===p.year?`<div class="promotion-summary"><span>${icon(progress.eligible?'trophy':'shield',17)}${progress.eligible?'Your promotion match is ready.':'Build recall. Show it again on later days.'}</span><button class="text-btn" data-action="promotion-info">Promotion goals ${icon('arrow',13)}</button></div>`:''}</section>`;
}
export function homeView(p){
 initCareer(p);const sum=profileSummary(p),v=levelProgress(p),plan=planSummary(p),progress=yearProgress(p),news=p.inbox.filter(n=>!n.read),nextClub=CLUBS.find(c=>!clubProgress(p,c).eligible),remaining=Math.max(0,probeIds(p).length-(p.placementProgress||0));
 return `${heading(`Year ${p.year} academy / ${esc(p.look.position)}`,`Ready, ${esc(p.name)}?`,`<button class="wallet-pill" data-action="nav" data-view="locker"><span>●</span> ${credits(p)} credits</button>`)}<div class="academy-hero-grid"><section class="academy-match-card"><div class="match-hero-copy"><span class="eyebrow">${clubBadge(p)} ${esc(clubById(p.look.club).name)} · Your game career</span><h2>Small shots.<br><em>Big progress.</em></h2><button class="btn lime big" data-action="${progress.eligible?'promotion':'play'}">${icon('play',18)}${progress.eligible?'Promotion match':p.placementComplete?'Play next match':p.placementProgress?'Continue warm-up':'Kick off'}</button><div class="match-hero-meta"><span>${icon('ball',13)}${p.placementComplete?'10 shots':`${remaining} warm-up shots`}</span><span>${icon('whistle',14)}Picked for you</span></div></div><div class="hero-player">${avatarSVG(p,{size:190})}<span>${esc(p.name)}<b>${p.look.number}</b></span></div></section>${goalsMarkup(p)}</div><div class="career-row"><section class="career-level-card">${icon('star',23)}${progressStrip(p)}${nav('locker','Your locker','arrow','text-btn')}</section><button class="career-record-card" data-action="nav" data-view="stats">${icon('trophy',25)}<span><b>${Math.max(0,...Object.values(p.records||{}).map(r=>r.points))}</b><small>Personal best XP</small></span>${icon('arrow',16)}</button><button class="career-record-card" data-action="news">${icon(news.length?'book':'shield',25)}<span><b>${news.length?`${news.length} new ${news.length===1?'note':'notes'}`:nextClub?esc(nextClub.name):'All-star'}</b><small>${news.length?'Academy news':nextClub?'Next career goal':'Keep your skills sharp'}</small></span>${icon('arrow',16)}</button></div>${yearJourney(p)}<div class="section-head"><h2>Coach’s next moves</h2><button class="text-btn" data-action="how">Why these? ${icon('whistle',15)}</button></div><div class="focus-strip">${plan.map(x=>`<div class="focus-card"><span>${{foundation:'+',tables:'×',written:'=',curriculum:'◇'}[x.lane]}</span><div><small>${{foundation:'First touch',tables:'Ball control',written:'Set pieces',curriculum:'Wider game'}[x.lane]}</small><b>${esc(skillById(x.id).title)}</b></div></div>`).join('')}</div><div class="session-ending-note">${icon('clock',15)} One short match is a good session. Your progress will be here next time.</div>`;
}
export function lockerView(p,slot='kit'){
 initCareer(p);const categories=[['kit','Kits'],['shorts','Shorts'],['boots','Boots'],['hair','Hair'],['accessory','Extras'],['ball','Balls'],['trail','Trails']];
 return `${heading('Build your player','The locker room.',`<span class="wallet-pill"><span>●</span>${credits(p)} credits</span>`)}<div class="locker-layout"><aside class="player-customiser"><div class="avatar-stage">${avatarSVG(p,{size:210})}<span class="avatar-name">${esc(p.name)}</span>${clubBadge(p)}<b class="current-club">${esc(clubById(p.look.club).name)}</b></div>${progressStrip(p)}<div class="custom-fields"><label>Kit number<input id="kit-number" class="field" inputmode="numeric" type="number" min="1" max="99" value="${p.look.number}"></label><label>Position<select class="field" id="kit-position">${POSITIONS.map(n=>`<option ${p.look.position===n?'selected':''}>${n}</option>`).join('')}</select></label></div><div class="custom-colours"><span>Skin tone</span><div>${Object.entries(SKIN_TONES).map(([id,c])=>`<button class="colour-swatch ${p.look.skin===id?'selected':''}" style="--swatch:${c}" data-action="skin" data-value="${id}" aria-label="Skin tone ${id}" aria-pressed="${p.look.skin===id}"></button>`).join('')}</div><span>Hair colour</span><div>${Object.entries(HAIR_COLOURS).map(([id,c])=>`<button class="colour-swatch ${p.look.hairColour===id?'selected':''}" style="--swatch:${c}" data-action="hair-colour" data-value="${id}" aria-label="${id} hair" aria-pressed="${p.look.hairColour===id}"></button>`).join('')}</div></div></aside><div class="locker-shop"><div class="shop-intro"><div><h2>Make it yours.</h2><p>Every 10 XP earns 1 credit.</p></div><span>${icon('shield',14)}Only earned credits</span></div><div class="shop-tabs" role="group" aria-label="Shop category">${categories.map(([id,label])=>`<button class="${id===slot?'active':''}" data-action="shop-tab" data-slot="${id}" aria-pressed="${id===slot}">${label}</button>`).join('')}</div><div class="shop-grid">${ITEMS.filter(item=>item.slot===slot).map(item=>{const owned=owns(p,item),equipped=p.look[item.slot]===item.id,locked=careerLevel(p)<item.level;return `<article class="shop-item ${equipped?'equipped':''}"><span class="shop-status">${equipped?'Wearing':owned?'Owned':`Level ${item.level}`}</span><div class="item-preview">${avatarSVG(p,{size:97,preview:item.id})}</div><h3>${item.name}</h3><button class="btn ${equipped?'soft':owned?'white':'lime'}" data-action="${owned?'equip':'buy'}" data-item="${item.id}" ${equipped||locked?'disabled':''}>${equipped?icon('check',14)+' Wearing':locked?`Level ${item.level}`:owned?'Wear it':`● ${item.price}`}</button></article>`;}).join('')}</div><section class="club-selection panel"><div class="section-head"><div><span class="eyebrow">Your football story</span><h2>Choose your club</h2></div>${icon('shield',23)}</div><div class="club-grid">${CLUBS.map(c=>`<button class="club-option ${p.look.club===c.id?'selected':''}" data-action="club" data-club="${c.id}" ${!clubProgress(p,c).eligible?'disabled':''}><span class="club-badge" style="--club-colour:${c.colour}">${esc(c.short)}</span><b>${esc(c.name)}</b><small>${p.look.club===c.id?'Your club':clubProgress(p,c).eligible?'Join club':clubProgress(p,c).remaining.map(g=>`${g.label}: ${Math.min(g.value,g.target)}/${g.target}`).join(' · ')}</small></button>`).join('')}</div><p class="small-print">Club offers need independent practice, a range of facts and recall on later days. They are fictional game rewards. Matchday Maths is independent of these clubs.</p></section></div></div>`;
}
export function leagueView(data,p,period='week',selectedYear=0){
 const rows=leagueTable(data.profiles,{period,year:selectedYear});
 return `${heading('Real players. Your shared device.','The squad league.',`<span class="small-tag">${icon('shield',14)}On this device</span>`)}<div class="league-toolbar"><div class="year-toggle"><button class="${period==='week'?'active':''}" data-action="league-period" data-period="week">Last 7 days</button><button class="${period==='all'?'active':''}" data-action="league-period" data-period="all">All-time</button></div><label class="sr-only" for="league-year">Leaderboard year</label><select class="field" id="league-year"><option value="0">Whole squad</option>${Array.from({length:6},(_,i)=>i+1).map(y=>`<option value="${y}" ${selectedYear===y?'selected':''}>Year ${y}</option>`).join('')}</select></div>${rows.length?`<section class="league-board">${rows.map(r=>`<article class="league-row ${r.profile.id===p?.id?'you':''}"><strong class="league-rank">${r.rank<=3?icon('trophy',23):r.rank}</strong><div class="league-avatar">${avatarSVG(r.profile,{size:54})}</div><div class="league-name"><h2>${esc(r.profile.name)} ${r.profile.id===p?.id?'<span>You</span>':''}</h2><small>${esc(r.profile.look?.position||'Player')} · ${esc(clubById(r.profile.look?.club).name)}</small></div><div class="league-stat"><b>${r.points}</b><small>League XP</small></div><div class="league-stat accuracy"><b>${r.accuracy}%</b><small>Accuracy</small></div></article>`).join('')}</section>`:`<section class="league-empty panel">${icon('trophy',48)}<h2>The first place is waiting.</h2><p>Finish a timed match with at least five shots to join the league.</p>${p?'<button class="btn lime" data-action="play">Play a match '+icon('arrow',17)+'</button>':'<button class="btn lime" data-action="new-player">Create a player '+icon('plus',17)+'</button>'}</section>`}<div class="league-explainer"><h3>How the league works</h3><p>Independent answers from completed timed matches earn league XP. Paused matches stay in personal progress. Reading support and dyslexia-friendly mode keep the same rewards. There are no invented opponents or public pupil listings.</p><button class="text-btn" data-action="players">Switch or add a player ${icon('arrow',14)}</button></div>`;
}
export function tablesView(p,{table=3,mode='auto',length=10}={}){
 const choices=focusTables(p.year);if(!choices.length)return `${heading('Build meaning first','Groups before tables.')}<div class="table-start panel"><div>${avatarSVG(p,{size:170})}</div><div><h2>Count. Group. Share.</h2><p>Year 1 begins with equal groups and pictures.</p><button class="btn lime" data-action="skill" data-skill="groups1">Equal groups ${icon('arrow',17)}</button><button class="btn white" data-action="skill" data-skill="share1">Share equally ${icon('arrow',17)}</button></div></div>`;
 if(table!=='all'&&!choices.includes(table))table=choices[0];const evidence=table==='all'?choices.map(t=>tableEvidence(p,t)).reduce((a,e)=>({total:a.total+e.total,direct:a.direct+e.direct,inverse:a.inverse+e.inverse,gaps:a.gaps+e.gaps,secure:a.secure+e.secure}),{total:0,direct:0,inverse:0,gaps:0,secure:0}):tableEvidence(p,table),modes=[['auto','Coach picks','Direct, inverse and missing facts'],['multiply','Recall','Multiplication facts'],['divide','Turn it around','Related division facts'],['missing','Find the gap','Missing factors'],['mixed','Mix it up','All three forms']];
 return `${heading(`Year ${p.year} / Ball control`,'The table gym.',`<span class="small-tag">${icon('shield',14)}Recall before speed</span>`)}<div class="table-gym-layout"><section class="table-session panel"><h2>Your next table match</h2><div class="gym-table-tabs" role="group" aria-label="Choose a table">${choices.map(t=>`<button data-action="gym-table" data-table="${t}" class="${table===t?'active':''}" aria-pressed="${table===t}">×${t}</button>`).join('')}<button data-action="gym-table" data-table="all" class="${table==='all'?'active':''}">Mixed</button></div><div class="gym-modes">${modes.map(([id,title,detail])=>`<button data-action="gym-mode" data-mode="${id}" class="${mode===id?'selected':''}" aria-pressed="${mode===id}"><b>${title}</b><small>${detail}</small>${icon(mode===id?'check':'ball',17)}</button>`).join('')}</div><div class="gym-length"><span>Match length</span><button class="${length===10?'active':''}" data-action="gym-length" data-length="10">10 shots</button><button class="${length===25?'active':''}" data-action="gym-length" data-length="25">25 shots</button></div><button class="btn lime big full" data-action="gym-play">Play table match ${icon('arrow',18)}</button></section><aside><section class="table-evidence panel"><span class="eyebrow">${table==='all'?'Mixed tables':'×'+table} / Your evidence</span><h2>More than a lucky run.</h2><div class="evidence-row"><span>${icon('ball',18)}Multiplication</span><b>${evidence.direct}/${evidence.total}</b></div><div class="evidence-row"><span>${icon('reset',18)}Inverse division</span><b>${evidence.inverse}/${evidence.total}</b></div><div class="evidence-row"><span>${icon('help',18)}Missing factors</span><b>${evidence.gaps}/${evidence.total}</b></div><div class="evidence-row fit"><span>${icon('shield',18)}Match fit</span><b>${evidence.secure}/${evidence.total}</b></div><p>Facts return on later days. A missed fact comes back after other questions.</p></section><div class="coach-note">Coach introduces up to three new fact families in a match and revisits earlier facts. Multiplication and division evidence stay separate.</div></aside></div><div id="table-tracker-host">${factMapMarkup(p,table==='all'?choices[0]:table)}</div>`;
}
export function syllabusView(p,year=1,domain='all',search=''){
 const ids=syllabusIds(year).filter(id=>(skillById(id).title+' '+(skillById(id).focus||'')).toLowerCase().includes(search.toLowerCase()));
 return `${heading('The basics of the curriculum',`Year ${year} training.`,`<div class="all-year-tabs" role="group" aria-label="Syllabus year">${Array.from({length:6},(_,i)=>i+1).map(y=>`<button class="${year===y?'active':''}" data-action="year" data-year="${y}" aria-pressed="${year===y}">${y}</button>`).join('')}</div>`)}${p?yearJourney(p,year):'<p class="syllabus-intro">Explore any year. Choose a player when you want to practise.</p>'}<div class="syllabus-tools"><input id="skill-search" class="search" type="search" aria-label="Find a skill" placeholder="Find a skill…" value="${esc(search)}"><a class="text-btn" href="../curriculum/">Curriculum guide ${icon('book',15)}</a></div><div class="filters" role="group" aria-label="Maths topic"><button class="filter ${domain==='all'?'active':''}" data-action="domain" data-domain="all">All</button>${DOMAINS.filter(d=>ids.some(id=>domainFor(skillById(id))===d.id)).map(d=>`<button class="filter ${domain===d.id?'active':''}" data-action="domain" data-domain="${d.id}">${d.title}</button>`).join('')}</div><div id="syllabus-bank">${syllabusCards(p,ids,domain)}</div>`;
}
export function syllabusCards(p,ids,domain='all'){
 return DOMAINS.filter(d=>domain==='all'||domain===d.id).map(d=>{const list=ids.filter(id=>domainFor(skillById(id))===d.id);if(!list.length)return '';return `<section class="domain-section"><div class="domain-title"><span class="domain-number">${d.symbol}</span><h2>${d.title}</h2><small>${list.length} skills</small></div><div class="curriculum-grid">${list.map(id=>{const sk=skillById(id),c=p?competency(p,id):{n:0,secure:false,ready:false};return `<article class="curriculum-card"><button data-action="skill" data-skill="${id}" aria-label="Practise ${esc(sk.title)}"><span class="curriculum-symbol">${sk.table?'×'+sk.table:d.symbol}</span><h3>${esc(sk.title)}${sk.digits?`<small>${sk.digits} digits${sk.regroup?' · exchange':' · no exchange'}</small>`:''}</h3>${icon('arrow',17)}<span class="status ${c.secure?'fit':c.n?'training':''}">${c.secure?'Match fit':c.ready?'Building on it':c.n?'Training':'New'}</span></button><details><summary>What this covers</summary><p>${esc(sk.focus||sk.description||sk.title)}</p></details></article>`;}).join('')}</div></section>`;}).join('')||'<div class="empty"><h3>No skills found.</h3><p>Try table, time or fraction.</p></div>';
}
export function progressView(p,records){
 const sum=profileSummary(p);return `${heading(`${esc(p.name)} / Your progress`,'The trophy room.',`<span class="wallet-pill">${icon('star',16)}Level ${careerLevel(p)}</span>`)}<div class="progress-top"><div>${avatarSVG(p,{size:130})}</div><div><h2>${careerXP(p)} XP earned</h2><p>${sum.factsSecure} fact families recalled on later days.</p>${progressStrip(p)}</div><div>${nav('league','Squad league','trophy')}${nav('locker','Locker room','coach')}</div></div>${yearJourney(p)}<section class="panel" style="margin-bottom:22px"><h2>Your personal bests</h2>${records}</section><div id="table-tracker-host">${factMapMarkup(p,focusTables(p.year)[0])}</div>`;
}
export function reportContent(p){
 const progress=yearProgress(p);return `<span class="eyebrow">Grown-up report · Academy Year ${p.year}</span><h2 id="dialog-title">${esc(p.name)}’s year goals</h2><p>${progress.secure}/${progress.total} digital families match fit. ${progress.checked}/${progress.practical.length} practical checks recorded.</p><div class="report-wrap"><table class="report"><thead><tr><th>Skill family</th><th>Attempts</th><th>Independent accuracy</th><th>Evidence</th></tr></thead><tbody>${progress.skills.map(s=>`<tr><td>${esc(s.title)}</td><td>${s.n}</td><td>${s.accuracy===null?'Not sampled':s.accuracy+'%'}</td><td>${s.secure?'Match fit':s.ready?'Ready to build on':s.n?'Training':'Not sampled'}</td></tr>`).join('')}</tbody></table></div><h3 style="margin-top:24px">Practical and reasoning checks</h3><p class="muted">A grown-up observes the activity and records it here. These checks are local records, not verified assessments.</p><div class="practical-list">${progress.practical.map(t=>`<label><input type="checkbox" data-practical="${t.id}" data-profile="${p.id}" ${t.done?'checked':''}><span><b>${t.title}</b><small>${t.detail}</small></span></label>`).join('')}</div><div class="coach-note">Academy promotion needs all year families match fit, these practical checks, and at least 90% independent accuracy in a 12-shot promotion match. This is a game milestone, not a school-year placement or an official assessment.</div><div class="dialog-actions"><button class="btn white" data-action="export-csv" data-id="${p.id}">Export scores</button><button class="btn" data-action="close-dialog">Done</button></div>`;
}
export function coachView(data,voices=[]){
 const british=britishVoices(voices);return `${heading('For grown-ups','Coach’s corner.')}<div class="coach-grid"><section class="panel"><div class="section-head"><h2>Your squad</h2><button class="text-btn" data-action="new-player">Add ${icon('plus',15)}</button></div>${data.profiles.length?data.profiles.map(p=>`<div class="profile-row"><span class="profile-dot">${p.look?.number||9}</span><div><strong>${esc(p.name)}</strong><small>Year ${p.year} · Level ${careerLevel(p)} · ${p.sessions.length} matches</small></div><button class="text-btn" data-action="report" data-id="${p.id}">Year goals</button><button class="text-btn" data-action="edit-player" data-id="${p.id}">Edit</button></div>`).join(''):'<p>Create a player to begin. No pupil names or scores are preloaded.</p>'}<div class="coach-note">Profiles and the squad league belong to this browser. Switching player keeps results separate. There are no passwords or online pupil accounts.</div></section><section class="panel"><h2>Reading and sound</h2><label class="setting-check"><input type="checkbox" id="dyslexia-setting" ${data.settings.dyslexia?'checked':''}> Dyslexia-friendly layout</label><label class="setting-check"><input type="checkbox" id="reduce-motion" ${data.settings.reduceMotion?'checked':''}> Reduce motion</label><label class="setting-check"><input type="checkbox" id="auto-read" ${data.settings.autoRead?'checked':''}> Read questions automatically</label><label class="voice-field" for="british-voice">British voice<select class="field" id="british-voice"><option value="">${british.length?'Choose automatically':'No en-GB voice available on this device'}</option>${british.map(v=>`<option value="${esc(v.voiceURI)}" ${data.settings.voiceURI===v.voiceURI?'selected':''}>${esc(v.name)}</option>`).join('')}</select></label><label class="voice-field" for="speech-rate">Speech pace<select id="speech-rate" class="field"><option value="0.75" ${data.settings.speechRate===.75?'selected':''}>Slower</option><option value="0.9" ${data.settings.speechRate===.9?'selected':''}>Steady</option><option value="1" ${data.settings.speechRate===1?'selected':''}>Normal</option></select></label><button class="text-btn" data-action="voice-test">${icon('sound',16)}Try the voice</button><p class="small-print">Voice availability and pronunciation depend on the browser and device. Reading support never reduces rewards.</p></section></div><section class="panel backup-panel"><div><h2>Keep a squad backup</h2><p>Clearing browser data removes local progress. Export a backup to move to another computer.</p></div><div class="data-buttons"><button class="btn white" data-action="backup">${icon('download',16)}Backup</button><button class="btn white" data-action="import">Restore</button><input type="file" id="import-file" accept=".json,application/json" hidden></div></section><section class="panel coach-rules"><h2>What drives practice and promotion?</h2><ol><li>A year-specific warm-up samples a starting point. It does not award mastery.</li><li>Coach balances weak prerequisites, a focus table, written methods, wider curriculum and due recall. Mistakes return after intervening questions.</li><li>Table families need separate multiplication and inverse-division evidence. At most three new table families enter a short match.</li><li>Match-fit evidence needs broad independent success on later days. Reviews use increasing intervals of 1, 3, 7, 14, 30 and 60 days.</li><li>Promotion requires the current year’s digital families, recorded practical checks and a successful promotion match. XP alone cannot promote a year.</li><li>Levels get further apart as XP rises. Credits are earned at 1 per 10 XP and buy only cosmetics. There are no payments, random prizes or lost rewards for missing a day.</li></ol><p>Changing a practice year in Edit does not award completion of earlier years. The curriculum map is for England; it does not claim a single uniform UK curriculum or guarantee permanent retention.</p><div class="sources"><a href="../curriculum/">Full curriculum guide</a><a href="../accessibility/">Accessibility</a><a href="../privacy/">Privacy</a></div></section>`;
}
